"""weights.json → packages/core/src/games/the-hunger/search/weights/<name>.gen.ts (base64 float32)."""
import base64, json, sys
import numpy as np

src, name = sys.argv[1], sys.argv[2]
w = json.load(open(f"{src}/weights.json"))
lines = [
    "// GENERATED by scripts/hunger-train/export_ts.py — do not edit.",
    f"// Source: {src}",
    "export const VALUE_NET = {",
    f"  featureVersion: {w['featureVersion']},",
    f"  features: {w['features']},",
    f"  heads: {json.dumps(w['heads'])},",
    "  layers: [",
]
for l in w["layers"]:
    W = np.asarray(l["w"], dtype="<f4")  # [out, in]
    b = np.asarray(l["b"], dtype="<f4")
    lines.append(f"    {{ out: {W.shape[0]}, in: {W.shape[1]}, w: \"{base64.b64encode(W.tobytes()).decode()}\", b: \"{base64.b64encode(b.tobytes()).decode()}\" }},")
lines += ["  ],", "} as const;", ""]
out = f"packages/core/src/games/the-hunger/search/weights/{name}.gen.ts"
open(out, "w").write("\n".join(lines))
print("wrote", out)
